// L2 scope (mirror: n8n/templates/law-change-scope.js)
/**
 * law-change-scope.js
 * L2 — deterministic impact scope + severity for the law-change-impact agent. No LLM.
 *
 * Given the changed articles of a law plus the relevant law_chunks / law_relations rows
 * (as the digest fetches them from Supabase), computes:
 *   - which services are affected, and
 *   - a per-service severity CEILING that is LEGAL, not demand-based (closes the viz-session
 *     note that edge thickness conflated demand with risk).
 *
 * Severity model (max over all paths from the changed article to the service):
 *   - the changed article directly serves the service (its service_slugs)  → high
 *   - reached via a verified `requires` / `overrides` relation              → high
 *   - via `clarifies`                                                       → medium
 *   - via `references`                                                      → low
 * Modulation: if the diff touches no substantive tokens (money / % / dates / terms / subsistence
 *   minimum), soften one step — a wording/structure edit is lower risk than a number change.
 * Only lawyer-verified relations (verified_by set) are traversed — an unverified graph edge
 * never drives an impact claim. The LLM (L3) proposes its own severity but is bounded ABOVE
 * by this ceiling.
 *
 * n8n entry point (paste into Code Node):
 *   const scope = computeImpactScope({
 *     changedArticles: $json.article_diffs.changed_articles,
 *     lawCode:         $json.law_code,
 *     lawChunks:       $json.law_chunks,     // [{ id, law_code, article_num, service_slugs }]
 *     lawRelations:    $json.law_relations,  // [{ from_chunk_id, to_chunk_id, relation_type, verified_by }]
 *     touchesNumbers:  diffTouchesNumbers($json.article_diffs),
 *   });
 *   return [{ json: { ...$json, scope } }];
 */

const SEVERITY_RANK = { low: 1, medium: 2, high: 3 };
const RELATION_CEILING = { requires: 'high', overrides: 'high', clarifies: 'medium', references: 'low' };

// Tokens that make a change legally "substantive" (quantitative / temporal). A diff touching
// none of these is treated as wording/structure → severity softened one step.
const SUBSTANTIVE_RE = /(грн|\d+\s*%|відсотк|\d+\/\d+|\d{2}\.\d{2}\.\d{4}|місяц|\bрок|\bдн[ів]|прожитков|мінімум|неоподатк)/i;

function maxSeverity(a, b) {
  return SEVERITY_RANK[a] >= SEVERITY_RANK[b] ? a : b;
}
function softer(sev) {
  return sev === 'high' ? 'medium' : 'low';
}

/** True if any diff hunk line touches a substantive (numeric / temporal) token. */
function diffTouchesNumbers(articleDiffs) {
  if (!articleDiffs || !Array.isArray(articleDiffs.hunks)) return false;
  return articleDiffs.hunks.some((h) =>
    [...(h.removed || []), ...(h.added || [])].some((line) => SUBSTANTIVE_RE.test(String(line))),
  );
}

/**
 * @param {object} args
 * @param {string[]} args.changedArticles
 * @param {string} args.lawCode
 * @param {Array} args.lawChunks       [{ id, law_code, article_num, service_slugs }]
 * @param {Array} args.lawRelations    [{ from_chunk_id, to_chunk_id, relation_type, verified_by }]
 * @param {boolean} [args.touchesNumbers=true]  default true = no softening (safe)
 * @returns {{ services: Array, changed_articles: string[], norms: string[] }}
 */
function computeImpactScope({ changedArticles, lawCode, lawChunks, lawRelations, touchesNumbers = true }) {
  const changed = new Set((changedArticles || []).map(String));
  const chunks = lawChunks || [];
  const relations = (lawRelations || []).filter((r) => r && r.verified_by);

  const changedChunks = chunks.filter((c) => c.law_code === lawCode && changed.has(String(c.article_num)));
  const changedIds = new Set(changedChunks.map((c) => c.id));
  const chunkById = new Map(chunks.map((c) => [c.id, c]));

  const acc = new Map(); // slug → { slug, severity, articles:Set, relations:Set }
  const bump = (slug, severity, articleNum, relation) => {
    if (!slug) return;
    const cur = acc.get(slug) || { slug, severity: 'low', articles: new Set(), relations: new Set() };
    cur.severity = maxSeverity(cur.severity, severity);
    if (articleNum != null) cur.articles.add(String(articleNum));
    if (relation) cur.relations.add(relation);
    acc.set(slug, cur);
  };

  // 1. Direct: the changed article itself serves these services → high.
  for (const c of changedChunks) {
    for (const slug of c.service_slugs || []) bump(slug, 'high', c.article_num, 'direct');
  }

  // 2. Ripple: verified relations incident to a changed chunk → the neighbor's services, at
  //    the relation type's ceiling.
  for (const r of relations) {
    const ceiling = RELATION_CEILING[r.relation_type] || 'low';
    let neighborId = null;
    if (changedIds.has(r.to_chunk_id)) neighborId = r.from_chunk_id;
    else if (changedIds.has(r.from_chunk_id)) neighborId = r.to_chunk_id;
    if (!neighborId) continue;
    const neighbor = chunkById.get(neighborId);
    if (!neighbor) continue;
    for (const slug of neighbor.service_slugs || []) bump(slug, ceiling, neighbor.article_num, r.relation_type);
  }

  const byArticleNum = (a, b) => parseInt(a, 10) - parseInt(b, 10);
  const services = [...acc.values()]
    .map((s) => ({
      slug: s.slug,
      severity: touchesNumbers ? s.severity : softer(s.severity),
      articles: [...s.articles].sort(byArticleNum),
      relations: [...s.relations],
    }))
    .sort((a, b) => SEVERITY_RANK[b.severity] - SEVERITY_RANK[a.severity] || a.slug.localeCompare(b.slug));

  const norms = [...new Set([...changed, ...services.flatMap((s) => s.articles)])].sort(byArticleNum);
  return { services, changed_articles: [...changed].sort(byArticleNum), norms };
}

// ── Exports (for Node.js testing; ignored in n8n Code Node) ───────────────────
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { computeImpactScope, diffTouchesNumbers };
}


const DIGEST_PROMPT_TEMPLATE = "Ти — юрист-аналітик. Закон змінився. Твоє завдання — НА ОСНОВІ НАДАНОГО DIFF коротко описати юристу-рецензенту, ЩО саме змінилося і ЯК це ймовірно впливає на кожну зачеплену послугу. Це ПОПЕРЕДНЯ чернетка для перевірки людиною, а не остаточний висновок.\n\n=== ВХІДНІ ДАНІ (підставляються автоматично) ===\n\nЗакон: {{LAW_TITLE}} (код {{LAW_CODE}})\nЗмінені статті: {{CHANGED_ARTICLES}}\n\nТекст змін (DIFF — рядки, що вилучені/додані; ЦЕ ЄДИНЕ ДЖЕРЕЛО ФАКТІВ):\n{{DIFF_HUNKS}}\n\nЗачеплені послуги та норми (L2-scope — лише ці послуги дозволено згадувати):\n{{SCOPE_SERVICES}}\n\nДозволені ідентифікатори статей (суворий список — лише ці можна цитувати):\n{{ALLOWED_ARTICLES}}\n\nДозволені slug послуг (суворий список):\n{{ALLOWED_SLUGS}}\n\n=== ПРАВИЛА (КРИТИЧНО — порушення → reject критиком L4a → abstention) ===\n\n1. **Тільки наданий DIFF.** Описуй ВИКЛЮЧНО те, що видно в `DIFF_HUNKS`. Не додавай знань «із пам'яті» про цей закон. Якщо diff незрозумілий або порожній — це сигнал утриматися (див. п.8).\n\n2. **Тільки дозволені цитати.** Згадуй статті ВИКЛЮЧНО з `ALLOWED_ARTICLES`. Жодних інших номерів статей.\n\n3. **Тільки дозволені послуги.** У `per_service[].slug` — ВИКЛЮЧНО значення з `ALLOWED_SLUGS`.\n\n4. **Жодних вигаданих чисел / дат / формул.** Якщо називаєш число, дату чи формулу — вона має бути ДОСЛІВНО присутня в `DIFF_HUNKS`. Не реконструюй «правильне» значення.\n\n5. **`evidence` — дослівна цитата з diff.** Поле `evidence` кожної послуги має бути фрагментом, скопійованим ДОСЛІВНО з `DIFF_HUNKS` (критик звіряє посимвольно).\n\n6. **severity — НЕ вище за стелю scope.** Для кожної послуги `severity` (`high`/`medium`/`low`) не може перевищувати стелю, вказану в `SCOPE_SERVICES`. Можна нижче — не вище.\n\n7. **Без юридичних гарантій.** Не пиши «суд зобов'язаний», «послуга зламана», «треба негайно». Пиши обережно: «ймовірно зачіпає», «потребує перевірки», «можливо стосується».\n\n8. **Невпевнений → коротше + нижча confidence.** Краще скромний правдивий опис, ніж впевнена вигадка. Якщо diff не дає підстав для висновку про конкретну послугу — НЕ вигадуй гіпотезу, постав `confidence` низько або не включай послугу.\n\n9. **Мова — українська.** Стиль — стислий, діловий. `summary` — 1–3 речення.\n\n=== ФОРМАТ ВІДПОВІДІ (суворий JSON, без markdown, без коментарів) ===\n\n{\n  \"summary\": \"<1–3 речення: що змінилось у законі, людською мовою>\",\n  \"per_service\": [\n    {\n      \"slug\": \"<∈ ALLOWED_SLUGS>\",\n      \"severity\": \"high|medium|low\",\n      \"confidence\": <0..1>,\n      \"articles\": [\"<∈ ALLOWED_ARTICLES>\"],\n      \"hypothesis\": \"<як ймовірно впливає на цю послугу — обережно>\",\n      \"evidence\": \"<ДОСЛІВНИЙ фрагмент з DIFF_HUNKS>\"\n    }\n  ],\n  \"overall_confidence\": <0..1>\n}\n";

function fillDigestPrompt(t, c) {
  return t
    .replace('{{LAW_TITLE}}',        c.LAW_TITLE)
    .replace('{{LAW_CODE}}',         c.LAW_CODE)
    .replace('{{CHANGED_ARTICLES}}', c.CHANGED_ARTICLES)
    .replace('{{DIFF_HUNKS}}',       c.DIFF_HUNKS)
    .replace('{{SCOPE_SERVICES}}',   c.SCOPE_SERVICES)
    .replace('{{ALLOWED_ARTICLES}}', c.ALLOWED_ARTICLES)
    .replace('{{ALLOWED_SLUGS}}',    c.ALLOWED_SLUGS);
}

// law_chunks.article_num is stored as "Стаття 182"; article_diffs.changed_articles are bare
// numbers ("182"). Normalise chunk article numbers so computeImpactScope can match them.
const artNum = (a) => { const m = String(a == null ? '' : a).match(/\d+(?:-\d+)?/); return m ? m[0] : ''; };

// n8n entry point. The fetch nodes run on a linear spine with alwaysOutputData, so an
// empty result still emits a placeholder item — filter those out by real-row shape.
const pending   = $('Fetch Pending').all().map((i) => i.json).filter((r) => r && r.id != null && r.article_diffs);
const chunksRaw = $('Fetch Chunks').all().map((i) => i.json).filter((c) => c && c.article_num != null);
const relations = $('Fetch Relations').all().map((i) => i.json).filter((r) => r && r.relation_type);
const model     = $('Global Config').first().json.GROQ_MODEL || 'llama-3.3-70b-versatile';

const chunks = chunksRaw.map((c) => ({ ...c, article_num: artNum(c.article_num) }));

const out = [];
for (const row of pending) {
  const ad = row.article_diffs || {};
  const changedArticles = (ad.changed_articles || []).map(String);
  const scope = computeImpactScope({
    changedArticles,
    lawCode: ad.law_code,
    lawChunks: chunks,
    lawRelations: relations,
    touchesNumbers: diffTouchesNumbers(ad),
  });

  const allowedArticles = [...new Set([...changedArticles, ...scope.norms.map(String)])];
  const allowedSlugs = scope.services.map((s) => s.slug);

  // Present removed/added lines VERBATIM (no inline +/− markers) under labelled blocks so
  // the model can copy an `evidence` line exactly — the deterministic critic matches it
  // character-for-character against the raw diff corpus.
  const diffText = (ad.hunks || [])
    .map((h) => {
      const rem = (h.removed || []).length ? 'ВИЛУЧЕНО:\n' + h.removed.join('\n') : '';
      const add = (h.added || []).length ? 'ДОДАНО:\n' + h.added.join('\n') : '';
      return '[ст.' + (h.article_num || '?') + ' | ' + (h.op || 'changed') + ']\n' + [rem, add].filter(Boolean).join('\n');
    })
    .join('\n\n');

  const scopeText = scope.services.length
    ? scope.services.map((s) => '- ' + s.slug + ' (стеля severity: ' + s.severity + '; статті: ' + s.articles.join(', ') + ')').join('\n')
    : '(жодної послуги в scope)';

  const prompt = fillDigestPrompt(DIGEST_PROMPT_TEMPLATE, {
    LAW_TITLE:        row.law_title || ad.law_code || '',
    LAW_CODE:         ad.law_code || '',
    CHANGED_ARTICLES: changedArticles.join(', ') || '(невідомо)',
    DIFF_HUNKS:       diffText || '(порожній diff)',
    SCOPE_SERVICES:   scopeText,
    ALLOWED_ARTICLES: allowedArticles.join(', ') || '(порожньо)',
    ALLOWED_SLUGS:    allowedSlugs.join(', ') || '(порожньо)',
  });

  out.push({ json: {
    _row_id: row.id,
    _article_diffs: ad,
    _scope: scope,
    _allowed_slugs: allowedSlugs,
    _model: model,
    _groq_body: {
      model,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [{ role: 'user', content: prompt }],
    },
  } });
}
return out;

// ═══════════════════════════════════════════════════════
// Critique & Decide (L4) — GENERATED by scripts/build-law-change-digest.mjs
// Edit n8n/templates/law-change-groundedness.js and re-run.
// ═══════════════════════════════════════════════════════

// L4a deterministic groundedness (mirror: n8n/templates/law-change-groundedness.js)
/**
 * law-change-groundedness.js
 * L4a critic — deterministic groundedness for the law-change-impact agent draft. No LLM.
 *
 * Verifies the L3 "what changed" draft against the GROUND TRUTH (the deterministic
 * article_diffs + the L2 scope). Any claim that can't be backed → RED span → abstention (L4c):
 * the digest then withholds the draft (ai_status='abstained') and the lawyer sees the diff only.
 *
 * Checks:
 *   1. each per_service.slug ∈ scope services (allowed_slugs)               → else RED
 *   2. each cited article (per_service.articles + "ст.N" in the prose) ∈
 *      allowed_articles (diff changed_articles ∪ scope.norms)              → else RED
 *   3. each per_service.evidence appears VERBATIM in the diff hunks         → else RED
 *
 * n8n entry point (paste into Code Node):
 *   const result = checkLawChangeGroundedness($json.ai_draft, {
 *     articleDiffs: $json.article_diffs,
 *     scope:        $json.scope,
 *   });
 *   return [{ json: { ...$json, groundedness: result } }];
 *
 * result.has_red === true → abstain.
 */

// "ст.182", "ст. 182", "статті 182", "стаття 182-1" → captures the article number.
const ARTICLE_CITE_RE = /(?:ст\.?|статт[іяею])\s*(\d+(?:-\d+)?)/gi;

/** Flatten every diff hunk line (removed + added) into one searchable corpus. */
function buildDiffCorpus(articleDiffs) {
  if (!articleDiffs || !Array.isArray(articleDiffs.hunks)) return '';
  const lines = [];
  for (const h of articleDiffs.hunks) {
    for (const l of h.removed || []) lines.push(String(l));
    for (const l of h.added || []) lines.push(String(l));
  }
  return lines.join('\n');
}

/** Set of article numbers cited in a free-text string. */
function citedArticles(text) {
  const out = new Set();
  for (const m of String(text || '').matchAll(ARTICLE_CITE_RE)) out.add(m[1]);
  return out;
}

function makeSpan(text, type, status, reason) {
  return { text, type, status, reason };
}

/**
 * @param {object} draft  L3 output { summary, per_service:[{slug,articles,hypothesis,evidence}] }
 * @param {object} ctx    { articleDiffs, scope }
 * @returns {{ spans: object[], has_red: boolean, has_amber: boolean }}
 */
function checkLawChangeGroundedness(draft, ctx = {}) {
  const spans = [];
  const d = draft || {};
  const articleDiffs = ctx.articleDiffs || {};
  const scope = ctx.scope || {};

  const allowedSlugs = new Set((scope.services || []).map((s) => s.slug));
  const allowedArticles = new Set([
    ...(articleDiffs.changed_articles || []).map(String),
    ...(scope.norms || []).map(String),
  ]);
  const corpus = buildDiffCorpus(articleDiffs);

  // 1–3: per-service items.
  for (const item of d.per_service || []) {
    if (item.slug && !allowedSlugs.has(item.slug)) {
      spans.push(makeSpan(item.slug, 'service', 'RED',
        `Послуга "${item.slug}" поза scope (L2). Можлива вигадка.`));
    }
    for (const a of item.articles || []) {
      if (!allowedArticles.has(String(a))) {
        spans.push(makeSpan(`ст.${a}`, 'citation', 'RED',
          `Стаття "${a}" поза дозволеним набором (diff ∪ scope). Можлива галюцинація.`));
      }
    }
    if (item.evidence && !corpus.includes(String(item.evidence).trim())) {
      spans.push(makeSpan(item.evidence, 'evidence', 'RED',
        'Цитата-доказ відсутня дослівно в diff. Можлива вигадка.'));
    }
  }

  // 2 (prose): articles cited in summary + each hypothesis must be allowed.
  const proseArticles = citedArticles(d.summary);
  for (const item of d.per_service || []) {
    for (const a of citedArticles(item.hypothesis)) proseArticles.add(a);
  }
  for (const a of proseArticles) {
    if (!allowedArticles.has(a)) {
      spans.push(makeSpan(`ст.${a}`, 'citation', 'RED',
        `Стаття "${a}" у тексті поза дозволеним набором. Можлива галюцинація.`));
    }
  }

  const has_red = spans.some((s) => s.status === 'RED');
  const has_amber = spans.some((s) => s.status === 'AMBER');
  return { spans, has_red, has_amber };
}

// ── Exports (for Node.js testing; ignored in n8n Code Node) ───────────────────
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { checkLawChangeGroundedness };
}


// n8n entry point (one item per pending row; row context via paired item):
const ctx = $('Compute Scopes').item.json;
const threshold = parseFloat($('Global Config').first().json.CONFIDENCE_THRESHOLD || '0.5');
const nowIso = new Date().toISOString();
const base = { _row_id: ctx._row_id, _model: ctx._model, _generated_at: nowIso };

// Parse the Groq strict-JSON response. Malformed/missing → error (diff still stands).
let draft = null;
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
  draft = JSON.parse(content);
} catch (e) {
  return [{ json: { ...base, _status: 'error', _summary: null, _impact: null, _confidence: null } }];
}
if (!draft || typeof draft !== "object") {
  return [{ json: { ...base, _status: 'error', _summary: null, _impact: null, _confidence: null } }];
}

// L4a — deterministic groundedness against the diff + L2 scope.
const g = checkLawChangeGroundedness(draft, { articleDiffs: ctx._article_diffs, scope: ctx._scope });
const conf = typeof draft.overall_confidence === 'number' ? draft.overall_confidence : 0;

// Clamp per-service severity to the deterministic L2 ceiling (LLM may go lower, never higher).
const RANK = { low: 1, medium: 2, high: 3 };
const ceil = {};
for (const s of (ctx._scope.services || [])) ceil[s.slug] = s.severity;
const clampedImpact = (draft.per_service || []).map((it) => {
  const c = ceil[it.slug];
  let sev = it.severity;
  if (c && RANK[sev] > RANK[c]) sev = c;
  return { ...it, severity: sev };
});

// Abstention (requirements §3.3): a RED span OR confidence below threshold → no draft.
if (g.has_red || conf < threshold) {
  return [{ json: { ...base, _status: 'abstained', _summary: null, _impact: null, _confidence: conf } }];
}

return [{ json: { ...base, _status: 'drafted', _summary: draft.summary || null, _impact: clampedImpact, _confidence: conf } }];
